n = int(input())
count = 0
if n == 0:
    count = 1
else:
    while n > 0:
        count = count + 1
        n = n // 10
print("Number of digits:", count)

n = int(input())
is_prime = True
if n < 2:
    is_prime = False
else:
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            is_prime = False
            break
if is_prime:
    print("Prime")
else:
    print("Not Prime")

s = input().lower()
if s == s[::-1]:
    print("Palindrome")
else:
    print("Not Palindrome")

s = input().lower()
vowels = 0
consonants = 0
for ch in s:
    if ch.isalpha():
        if ch in "aeiou":
            vowels += 1
        else:
            consonants += 1
print("Vowels:", vowels)
print("Consonants:", consonants)

numbers = list(map(int, input().split()))
largest = numbers[0]
for num in numbers:
    if num > largest:
        largest = num
print("Largest element:", largest)

numbers = list(map(int, input().split()))
result = []
for num in numbers:
    if num not in result:
        result.append(num)
print(result)

def check_even_odd(n):
    if n % 2 == 0:
        return "Even"
    else:
        return "Odd"

num = int(input())
print(check_even_odd(num))

sentence = input().lower()
words = sentence.split()
frequency = {}
for word in words:
    if word in frequency:
        frequency[word] += 1
    else:
        frequency[word] = 1
print(frequency)

